css:
.dcx,.dcx{margin:0;padding:0;background:#FFFFFF;font-family:'Plus Jakarta Sans',system-ui,sans-serif;color:#0B2018;-webkit-font-smoothing:antialiased}
.dcx a{color:#0B3B29;text-decoration:none}
.dcx a:hover{color:#0E8A52}
.dcx [data-z] div,.dcx [data-z] span,.dcx [data-z] a,.dcx h1,.dcx [data-h1]{white-space:nowrap}
.dcx [data-z] p,.dcx [data-z] p *,.dcx [data-z] h2,.dcx [data-z] h2 *,.dcx [data-z] [data-wrap],.dcx [data-z] [data-wrap] *{white-space:normal}
.dcx [data-z][style*='max-width:778px'],.dcx [data-z][style*='max-width: 778px']{max-width:1024px!important}
@keyframes nxFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-5px)}}
@media (min-width:1040px){.dcx [data-z]{zoom:1.3}
}
@media (min-width:1300px){.dcx [data-z]{zoom:1.6}
}
@media (max-width:820px){.dcx [data-c]{grid-template-columns:minmax(0,1fr)!important;justify-items:center;row-gap:22px}
.dcx [data-c]>*{max-width:100%}
.dcx [data-hero]{flex-direction:column;align-items:center;height:auto!important;padding-bottom:24px}
.dcx [data-nav]{display:none!important}
.dcx [data-g4],.dcx [data-g5]{grid-template-columns:repeat(2,minmax(0,1fr))!important}
.dcx [data-g3]{grid-template-columns:minmax(0,1fr)!important}
.dcx [data-tbl]{overflow-x:auto}
}
@media (max-width:520px){.dcx [data-v]{zoom:.72}
.dcx [data-g4],.dcx [data-g5]{grid-template-columns:minmax(0,1fr)!important}
.dcx [data-row]{flex-wrap:wrap}
.dcx [data-h1]{font-size:30px!important;line-height:32px!important}
}

.dch-df2ff70f:hover{transform:translateY(-2px) !important;color:#FFFFFF !important}
.dch-aa15b40d:hover{transform:translateY(-3px) !important}
.dch-ced5ac0e:hover{background:rgba(255,255,255,.10) !important}
.dch-552142ad:hover{transform:translateY(-2px) !important;box-shadow:0 10px 22px -12px rgba(11,59,41,.35) !important;color:#0B2018 !important}
.dch-227f5dfd:hover{transform:translateY(-2px) !important;color:#0B2018 !important}
